import{_ as n,o,c as s,ag as r,j as d}from"./chunks/framework.KxDd3USm.js";const _=JSON.parse('{"title":"08.3 防火墙、常见攻击与恶意代码 ★★","description":"","frontmatter":{},"headers":[],"relativePath":"08-信息安全/03-防火墙攻击与恶意代码.md","filePath":"08-信息安全/03-防火墙攻击与恶意代码.md"}'),e={name:"08-信息安全/03-防火墙攻击与恶意代码.md"},a={class:"fig"},g={"data-figure-id":"figure-47",viewBox:"0 0 720 268",width:"100%",style:{"max-width":"720px"},role:"img","aria-label":"两条路径对照：上路包过滤防火墙只核对包头部的源目的 IP 和端口，端口相符即放行，URL 内容原样穿墙进入外网服务器；下路应用代理防火墙终结内外两侧连接，完整解析应用协议并检查 URL 命令内容，符合规则才重新构造请求转发，原始包不直通"};function h(u,t,l,i,q,x){return o(),s("div",null,[t[2]||(t[2]=r('<h1 id="_08-3-防火墙、常见攻击与恶意代码-★★" tabindex="-1">08.3 防火墙、常见攻击与恶意代码 ★★ <a class="header-anchor" href="#_08-3-防火墙、常见攻击与恶意代码-★★" aria-label="Permalink to &quot;08.3 防火墙、常见攻击与恶意代码 ★★&quot;">​</a></h1><p><strong>动机</strong>：加密和签名保的是&quot;数据本身&quot;，而防火墙保的是&quot;网络边界&quot;——像小区门禁，控制什么人能进、什么包能过。</p><h3 id="_6-1-防火墙是什么" tabindex="-1">6.1 防火墙是什么 <a class="header-anchor" href="#_6-1-防火墙是什么" aria-label="Permalink to &quot;6.1 防火墙是什么&quot;">​</a></h3><p>位于<strong>内部网络与外部网络（Internet）之间</strong>的屏障，按规则<strong>控制进出网络的数据包与流向</strong>，是内外网之间信息流的唯一通道。</p><h3 id="_6-2-两种常考类型" tabindex="-1">6.2 两种常考类型 <a class="header-anchor" href="#_6-2-两种常考类型" aria-label="Permalink to &quot;6.2 两种常考类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比项</th><th>包过滤防火墙</th><th>应用代理防火墙（应用网关）</th></tr></thead><tbody><tr><td>工作层次</td><td><strong>网络层</strong>（有的含传输层）</td><td><strong>应用层</strong></td></tr><tr><td>检查内容</td><td>数据包的<strong>源/目的 IP、端口</strong>等头部信息</td><td><strong>具体应用协议的内容</strong>（如 URL、命令）</td></tr><tr><td>是否转发原始包</td><td>直接放行/丢弃，内外<strong>直通</strong></td><td>内外<strong>不直通</strong>，代理替两头转接</td></tr><tr><td>优点</td><td>快、开销小、透明</td><td>安全控制粒度细、能审计内容</td></tr><tr><td>缺点</td><td>看不懂应用内容，挡不住应用层攻击</td><td>速度慢、每种协议要单独代理</td></tr></tbody></table><p>（另有&quot;状态检测&quot;防火墙，跟踪连接状态，介于两者之间，选择题见过即可。）</p><p>同一句危险请求 <code>GET /admin.php</code>，穿过两种防火墙是两种命运——差别全在&quot;它看包到哪一层&quot;：</p>',8)),d("figure",a,[(o(),s("svg",g,[...t[0]||(t[0]=[r('<defs><marker id="fw-a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="var(--ink)"></path></marker></defs><text class="tt" x="20" y="24">路径 A：包过滤——只看信封（网络层，快）</text><rect class="host" x="20" y="40" width="86" height="46" rx="8"></rect><text class="st" x="63" y="60">内网主机</text><text class="mt" x="63" y="76">发出请求</text><path class="e" d="M106 63 H186" marker-end="url(#fw-a)"></path><text class="mt" x="146" y="52">GET /admin.php</text><rect class="fwA" x="190" y="34" width="220" height="58" rx="10"></rect><text class="kd" x="300" y="52">包过滤防火墙（查包头）</text><text class="st" x="300" y="70">源/目的 IP ✓　端口 ✓</text><text class="st" x="300" y="85">内容？没看</text><path class="e" d="M410 63 H490" marker-end="url(#fw-a)"></path><rect class="host" x="494" y="40" width="100" height="46" rx="8"></rect><text class="st" x="544" y="60">外网服务器</text><text class="mt" x="544" y="76">收到危险 URL</text><text class="rd" x="300" y="112">端口对得上就放行 → 应用层攻击穿墙而过（它的缺点）</text><text class="tt" x="20" y="146">路径 B：应用代理——开箱验货（应用层，细）</text><rect class="host" x="20" y="160" width="86" height="46" rx="8"></rect><text class="st" x="63" y="180">内网主机</text><text class="mt" x="63" y="196">发出请求</text><path class="e" d="M106 183 H186" marker-end="url(#fw-a)"></path><rect class="fwB" x="190" y="154" width="220" height="58" rx="10"></rect><text class="kg" x="300" y="172">应用代理（应用网关）</text><text class="st" x="300" y="190">终结连接 → 解析完整协议</text><text class="st" x="300" y="205">检查 URL / 命令，合规才重建转发</text><path class="e" d="M410 183 H490" marker-end="url(#fw-a)"></path><rect class="host" x="494" y="160" width="100" height="46" rx="8"></rect><text class="st" x="544" y="180">外网服务器</text><text class="mt" x="544" y="196">只见代理的&quot;复制件&quot;</text><text class="rd" x="640" y="187">内外不直通</text><text class="mt" x="300" y="232">两侧连接在代理处断开重接：代理替两头各跑一段，所以能读内容、能审计，代价是慢、每种应用协议都要配代理</text><text class="mt" x="300" y="256">对照锚点：查 IP/端口 = 包过滤；查 URL/命令内容 = 应用代理——题干看&quot;检查对象&quot;选类型</text>',32)])])),t[1]||(t[1]=d("figcaption",null,'这就是速查表第三、四行的画面版：包过滤"直通"、代理"不直通"；精华题第 3 题考"层次 × 检查内容"互换的错配，用这张图两秒对回。',-1))]),t[3]||(t[3]=r('<h3 id="_6-3-三种经典部署体系结构-补充-属认知拓宽-非真题高频" tabindex="-1">6.3 三种经典部署体系结构（补充，属认知拓宽，非真题高频） <a class="header-anchor" href="#_6-3-三种经典部署体系结构-补充-属认知拓宽-非真题高频" aria-label="Permalink to &quot;6.3 三种经典部署体系结构（补充，属认知拓宽，非真题高频）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>体系结构</th><th>特征</th><th>一句话理解</th></tr></thead><tbody><tr><td><strong>双宿主主机（Dual-Homed Host）</strong></td><td>一台主机装<strong>两块网卡</strong>，分别接内网、外网，主机上<strong>关闭 IP 路由转发</strong>，成为内外网之间的唯一&quot;闸门&quot;</td><td>一台&quot;两头堵&quot;的机器，掐断内外直连、全要靠它转</td></tr><tr><td><strong>屏蔽主机（Screened Host）</strong></td><td>一台<strong>屏蔽路由器</strong>（包过滤）在外层先筛普通流量，另配一台<strong>堡垒主机</strong>负责接待必须进入内部的关键服务</td><td>&quot;路由在前粗筛 + 主机在后守关键服务&quot;</td></tr><tr><td><strong>屏蔽子网（Screened Subnet / DMZ 非军事区）</strong></td><td>内外网之间再用一道路由器<strong>隔出一段子网</strong>，把对外服务（Web、Mail）放在这中间缓冲带</td><td>&quot;两层路由夹一段缓冲子网，公网服务放中间的格子里&quot;</td></tr></tbody></table><p>直觉：这套体系是按&quot;边界防御的层次&quot;从单薄到周密排列的——一台机器当闸门（双宿主）→ 一层路由加一台主机（屏蔽主机）→ 两层路由夹一段缓冲子网（屏蔽子网/DMZ）。选择题若问&quot;把对外服务器放在内外网之间的隔离缓冲区&quot;指哪个，答<strong>屏蔽子网（DMZ）</strong>。</p><h3 id="_6-4-防火墙的-能与不能-送分判断题" tabindex="-1">6.4 防火墙的&quot;能与不能&quot;（送分判断题） <a class="header-anchor" href="#_6-4-防火墙的-能与不能-送分判断题" aria-label="Permalink to &quot;6.4 防火墙的&quot;能与不能&quot;（送分判断题）&quot;">​</a></h3><p><strong>能</strong>：控制进出数据包与流向；提供流量日志与审计；隐藏内部 IP 与网络结构细节（NAT）。</p><p><strong>不能</strong>（真题三连）：</p><ul><li>不能防范<strong>内部</strong>人员的攻击（它在边界上，管不着墙内）；</li><li>不能防范<strong>不经过它的</strong>连接（如内部拨号直连外网）；</li><li><strong>不能防病毒</strong>——它按 IP/端口/规则过滤，不做代码级查毒；&quot;漏洞扫描&quot;也不是它的功能。</li></ul><h3 id="_6-5-入侵检测系统-ids" tabindex="-1">6.5 入侵检测系统（IDS） <a class="header-anchor" href="#_6-5-入侵检测系统-ids" aria-label="Permalink to &quot;6.5 入侵检测系统（IDS）&quot;">​</a></h3><p><strong>动机</strong>：防火墙是&quot;门禁&quot;，但进了门或绕过门的人干坏事谁盯着？<strong>入侵检测系统 IDS</strong> 监视网络/系统，发现可疑行为<strong>报警</strong>。</p><ul><li>定位：<strong>监测 + 告警</strong>，是防火墙之后的第二道防线；<strong>本身不负责拦截阻断</strong>。</li><li>与 IPS 对照：IPS（入侵防御系统）串在通信路径上，检测到恶意行为会<strong>直接阻断</strong>；IDS 通常旁路监听，只报警不断流。题干出现&quot;自动阻断/拦截攻击&quot;选 IPS，出现&quot;监视并报警&quot;选 IDS。</li><li>采集方式：从网络抓包分析（基于网络）或读主机审计日志（基于主机）。</li></ul><p><strong>应试动作</strong>：背&quot;包过滤=网络层看头，应用代理=应用层看内容；防火墙不防内部、不防病毒、不管绕道的；IDS 只报警、IPS 会拦截&quot;。这四句覆盖本节所有真题考法。</p><hr><h2 id="第七节-常见攻击与恶意代码-★★" tabindex="-1">第七节 常见攻击与恶意代码 ★★ <a class="header-anchor" href="#第七节-常见攻击与恶意代码-★★" aria-label="Permalink to &quot;第七节 常见攻击与恶意代码 ★★&quot;">​</a></h2><p><strong>动机</strong>：前面学的都是&quot;防御方&quot;，本节换到&quot;进攻方&quot;视角——考场上给一段场景描述，让你指出&quot;这是什么攻击&quot;，认得出才能答对。</p><h3 id="_7-1-攻击类型认领表" tabindex="-1">7.1 攻击类型认领表 <a class="header-anchor" href="#_7-1-攻击类型认领表" aria-label="Permalink to &quot;7.1 攻击类型认领表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>攻击</th><th>场景特征（题干关键词）</th><th>防御</th></tr></thead><tbody><tr><td><strong>重放攻击</strong></td><td>截获合法报文，<strong>事后原样重发</strong>骗系统（主战场是身份认证）</td><td><strong>时间戳</strong>、<strong>一次性口令/一次性令牌</strong>、挑战-应答、序列号</td></tr><tr><td><strong>DoS/DDoS</strong></td><td>海量请求<strong>淹没</strong>服务器，耗尽带宽/连接资源，<strong>合法用户进不来</strong>（破坏可用性）；DDoS = 僵尸网络里成千上万台&quot;肉鸡&quot;同时发起</td><td>流量清洗、限流、CDN 分散</td></tr><tr><td><strong>SQL 注入</strong></td><td>在<strong>输入框/URL 参数</strong>里夹带 SQL 片段，骗数据库执行（如 <code>&#39; or &#39;1&#39;=&#39;1</code> 绕过登录）</td><td><strong>参数化查询（预编译语句）</strong>、过滤特殊字符、最小权限（联动 <a href="/ruankao/02-数据库系统/05-SQL.html">02-数据库系统.md</a>）</td></tr><tr><td><strong>钓鱼攻击</strong></td><td>仿冒官网/邮件诱骗用户主动<strong>交出</strong>账号密码</td><td>核对域名、不点陌生链接</td></tr><tr><td><strong>窃听/流量分析</strong></td><td>只监听不修改（被动攻击，见第一节）</td><td>加密</td></tr><tr><td><strong>伪装/假冒</strong></td><td>冒充合法用户或主机</td><td>身份认证、数字签名</td></tr><tr><td><strong>IP 欺骗</strong></td><td>伪造数据包的<strong>源 IP 地址</strong>，冒充可信主机（如内网地址）骗取对方信任</td><td>认证、过滤可信源地址、加密</td></tr><tr><td><strong>会话劫持</strong></td><td>中途<strong>插入/接管</strong>已建立的合法会话，冒充其中一方继续通信（常配合嗅探拿到会话标识）</td><td>会话加密、会话标识随机化、超时注销</td></tr><tr><td><strong>中间人攻击</strong></td><td>从通信一开始就偷偷插在两头<strong>中间转发并可能篡改</strong>消息，双方都以为在和对方直连；经典形态是冒充对方分发公钥——把&quot;自己的公钥&quot;当作&quot;A 的公钥&quot;发给 B（02.2 节证书一节见过这一幕）</td><td>用<strong>数字证书</strong>向可信第三方验明公钥、通信全程加密、核对密钥指纹</td></tr><tr><td><strong>暴力破解（口令攻击/字典攻击）</strong></td><td>用程序按<strong>字典或穷举</strong>不停试口令，赌你设了弱口令；针对登录口、远程管理口</td><td>强口令策略（长度+复杂度）、连续失败<strong>锁定账户</strong>、验证码、二次验证</td></tr><tr><td><strong>资源使用攻击（资源耗尽）</strong></td><td>占用服务器<strong>资源</strong>（连接数、内存、CPU）让合法请求没资源可用；DDoS 是其大规模化形态</td><td>限流、连接数上限、负载均衡</td></tr><tr><td><strong>后门 / 特洛伊陷阱</strong></td><td>攻击者事先在系统里<strong>留下隐蔽入口</strong>，随时绕过正常认证进入</td><td>全面补丁、基线核查、最小权限、网络隔离</td></tr></tbody></table><p><strong>重放 vs DDoS 一句话分清</strong>：重放是&quot;把<strong>旧的</strong>合法报文再发一遍&quot;骗认证；DDoS 是&quot;发<strong>海量的</strong>垃圾报文&quot;拖垮服务。</p><p><strong>中间人 vs 会话劫持一句话分清</strong>：中间人从通信建立<strong>之初</strong>就冒充&quot;信使&quot;藏在中间（题干关键词：转发、冒充公钥分发、双方不知情）；会话劫持是会话已经建立好，攻击者<strong>接管</strong>其中一方的身份继续玩（关键词：接管、已有会话）。两者都算主动攻击。</p><h3 id="_7-2-恶意代码四兄弟-背区别" tabindex="-1">7.2 恶意代码四兄弟（背区别） <a class="header-anchor" href="#_7-2-恶意代码四兄弟-背区别" aria-label="Permalink to &quot;7.2 恶意代码四兄弟（背区别）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>定义要点</th><th>区别关键</th></tr></thead><tbody><tr><td><strong>计算机病毒</strong></td><td>依附于<strong>宿主程序</strong>、能自我复制、破坏功能或数据的代码</td><td><strong>必须有宿主</strong>，靠寄生的程序/文件传播</td></tr><tr><td><strong>蠕虫</strong></td><td><strong>独立程序</strong>，利用系统漏洞<strong>自我复制</strong>、主动在网络传播</td><td><strong>不需要宿主、不需要人操作</strong>，自己爬</td></tr><tr><td><strong>木马</strong></td><td>伪装成正常软件，隐藏在受害机器里开&quot;后门&quot;，供攻击者<strong>远程控制</strong></td><td>靠&quot;伪装+远程控制&quot;获利，<strong>不自我复制</strong></td></tr><tr><td><strong>逻辑炸弹</strong></td><td>平时潜伏，<strong>满足特定条件</strong>（日期、事件）时爆发破坏</td><td><strong>条件触发</strong></td></tr></tbody></table><p><strong>记忆口诀</strong>：&quot;病毒寄生、蠕虫自爬、木马开门、炸弹看日子&quot;。四者共同点：都是恶意代码；考场上抓题干关键词——&quot;寄生在正常程序中&quot;选病毒，&quot;利用漏洞自主传播&quot;选蠕虫，&quot;远程控制/后门&quot;选木马，&quot;某日触发&quot;选逻辑炸弹。</p><p><strong>补充一个相关概念（DDoS 的&quot;作案工具&quot;）——僵尸网络</strong>：攻击者先用木马/蠕虫等手段<strong>批量感染</strong>大量主机，这些被控主机被称为&quot;<strong>僵尸机/肉鸡</strong>&quot;，它们组成的受控集群就叫<strong>僵尸网络（Botnet）</strong>。发起 DDoS 攻击时，攻击者只是向网络里的肉鸡群下达&quot;同时向目标狂发请求&quot;的命令——所以 DDoS 的流量面广、难以追溯到真凶。识别特征：题干说&quot;攻击者控制了大量被入侵的计算机同时发起攻击&quot;→ 僵尸网络。</p><p><strong>防毒常识</strong>（顺带背）：不打开来历不明附件、及时打补丁、升级杀毒软件<strong>特征库</strong>、重要数据备份。</p><hr>',24))])}const p=n(e,[["render",h]]);export{_ as __pageData,p as default};
